import random

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.size = 1
        self.count = 1
        self.priority = random.random()

def size(node):
    return node.size if node else 0

def update(node):
    if node:
        node.size = node.count + size(node.left) + size(node.right)

def rotate_left(node):
    new_root = node.right
    node.right = new_root.left
    new_root.left = node
    update(node)
    update(new_root)
    return new_root

def rotate_right(node):
    new_root = node.left
    node.left = new_root.right
    new_root.right = node
    update(node)
    update(new_root)
    return new_root

def insert(node, val):
    if not node:
        return Node(val)
    if val == node.val:
        node.count += 1
    elif val < node.val:
        node.left = insert(node.left, val)
        if node.left.priority < node.priority:
            node = rotate_right(node)
    else:
        node.right = insert(node.right, val)
        if node.right.priority < node.priority:
            node = rotate_left(node)
    update(node)
    return node

def remove(node, val):
    if not node:
        return None
    if val == node.val:
        if node.count > 1:
            node.count -= 1
        else:
            if not node.left and not node.right:
                return None
            elif not node.left or (node.right and node.left.priority < node.right.priority):
                node = rotate_left(node)
                node.left = remove(node.left, val)
            else:
                node = rotate_right(node)
                node.right = remove(node.right, val)
    elif val < node.val:
        node.left = remove(node.left, val)
    else:
        node.right = remove(node.right, val)
    update(node)
    return node

def get(node, k):
    # k-th smallest, 1-indexed
    left_size = size(node.left)
    if k <= left_size:
        return get(node.left, k)
    elif k <= left_size + node.count:
        return node.val
    else:
        return get(node.right, k - left_size - node.count)

class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        tree = None
        ans = []
        for i, x in enumerate(nums):
