from functools import lru_cache
from itertools import chain
from typing import List


class Solution:
    def minCost(self, n: int, cuts: List[int]) -> int:

        cuts = sorted(chain(cuts, [0, n]))

        @lru_cache(None)
        def dfs(l, r):
            length, M = cuts[r] - cuts[l], range(l + 1, r)
            return min((length + dfs(l, i) + dfs(i, r) for i in M),
                       default=0)

        return dfs(0, len(cuts) - 1)
```

**Bug fixed:** In the original, `min(..., default=length) + length` made a segment with no internal cuts return `2 * length` instead of `0` (e.g., `n=2, cuts=[1]` returned 6 instead of 2). Moving the cost `length` inside the generator and setting `default=0` makes the base case (adjacent cut points) cost 0, while a segment with cuts pays `length + min(subcosts)` — verified on `n=7, cuts=[1,3,4,5]`, which now correctly yields 16.

