class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])

        def dfs(i, j):
            if i < 0 or j < 0 or grid[i][j] == 0:
                return False
            if i == 0 and j == 0:
                return True
            grid[i][j] = 0
            return dfs(i - 1, j) or dfs(i, j - 1)

        if not dfs(m - 1, n - 1):
            return True

        # BFS from (0,0)
        q = deque([(0, 0)])
        grid[0][0] = 0
        while q:
            if len(q) == 1 and q[0] != (m - 1, n - 1):
                return True
            for _ in range(len(q)):
                i, j = q.popleft()
                for di, dj in ((1, 0), (0, 1)):
                    ni, nj = i + di, j + dj
                    if ni < m and nj < n and grid[ni][nj] == 1:
                        grid[ni][nj] = 0
                        q.append((ni, nj))
